def runs_bounded(mat, target, delim, dirs=((0,1),(1,0))):
    R,Cc=len(mat),len(mat[0]); selected=set()
    for dr,dc in dirs:
      starts=[]
      for r in range(R):
       for c in range(Cc):
        if (dr==0 and c!=0) or (dc==0 and r!=0):continue
        # line start criterion by predecessor out of bound
        if r-dr>=0 and r-dr<R and c-dc>=0 and c-dc<Cc: continue
        cells=[]; rr,cc=r,c
        while 0<=rr<R and 0<=cc<Cc:
          cells.append((rr,cc));rr+=dr;cc+=dc
        i=0
        while i<len(cells):
          if mat[cells[i][0]][cells[i][1]]!=target: i+=1;continue
          j=i
          while j<len(cells) and mat[cells[j][0]][cells[j][1]]==target:j+=1
          if i>0 and j<len(cells) and mat[cells[i-1][0]][cells[i-1][1]]==delim and mat[cells[j][0]][cells[j][1]]==delim:
            selected.update(cells[i:j])
          i=j
    return selected
